export const marqueeRecipe = tv({
  slots: {
    base: ["group/marquee", "relative", "w-full max-w-full", "isolate"],
    content: [
      "flex",
      "min-w-max",
      "delay-(--marquee-delay)",
      "data-[orientation=vertical]:animate-marquee-y data-[orientation=vertical]:flex-col",
      "data-[orientation=horizontal]:animate-marquee-x data-[orientation=horizontal]:flex-row",
      "data-reverse:direction-[reverse]!",
      "group-data-paused/marquee:paused!",
      "motion-reduce:animate-none!",
    ],
    edge: [
      "absolute z-10",
      "group-data-[orientation=horizontal]/marquee:h-full group-data-[orientation=horizontal]/marquee:w-1/4",
      "group-data-[orientation=vertical]/marquee:h-1/4 group-data-[orientation=vertical]/marquee:w-full",
      "pointer-events-none",
      "from-background to-transparent",
      "data-[side=start]:bg-linear-to-r",
      "data-[side=end]:bg-linear-to-l",
      "data-[side=top]:bg-linear-to-b",
      "data-[side=bottom]:bg-linear-to-t",
    ],
    item: ["w-full text-nowrap"],
    viewport: ["flex overflow-hidden"],
  },
});

export type MarqueeVariantProps = VariantProps<typeof marqueeRecipe>;
export type MarqueeRecipe = ReturnType<typeof marqueeRecipe>;
export type MarqueeRecipeSlot = keyof MarqueeRecipe;

editable.content:
import { tv, type VariantProps } from "tailwind-variants";

export const editableRecipe = tv({
  slots: {
    area: "w-full",
    base: [
      "group/editable",
      "relative",
      "w-full",
      "data-[orientation=vertical]:items-end",
      "flex items-center gap-2",
    ],
    control: [
      "group-data-[orientation=vertical]/editable:flex-col",
      "inline-flex items-center gap-2",
    ],
    preview: [
      "w-full justify-start",
      "px-3",
      "whitespace-pre-wrap font-normal text-base sm:text-sm",
      "transition-colors duration-fast ease-out",
      "dark:hover:bg-input/32",
      "data-placeholder-shown:text-muted-foreground",
      "in-[[data-scope=editable][data-part=area]:has(textarea)]:items-start",
      "motion-reduce:transition-none!",
    ],
  },
});

export type EditableVariantProps = VariantProps<typeof editableRecipe>;
export type EditableRecipe = ReturnType<typeof editableRecipe>;
export type EditableRecipeSlot = keyof EditableRecipe;

toggle.content:
import { tv, type VariantProps } from "tailwind-variants";

export const toggleRecipe = tv({
  base: [
    "relative",
    "data-[state=on]:bg-card data-[state=on]:shadow-sm dark:data-[state=on]:bg-input/64",
    "transition-transform duration-fast ease-out",
    "active:scale-[0.97]",
    "pointer-coarse:after:absolute pointer-coarse:after:size-full pointer-coarse:after:min-h-11 pointer-coarse:after:min-w-11",
    "motion-reduce:transition-none! motion-reduce:active:scale-100",
  ],
  defaultVariants: {
    size: "md",
  },
  variants: {
    size: {
      lg: "h-9 min-w-9 px-2.5",
      md: "h-8 min-w-8 px-2",
      sm: "h-7 min-w-7 px-1.5",
    },
  },
});

export type ToggleVariantProps = VariantProps<typeof toggleRecipe>;
export type ToggleRecipe = ReturnType<typeof toggleRecipe>;
export type ToggleRecipeSlot = keyof ToggleRecipe;

separator.content:
import { tv, type VariantProps } from "tailwind-variants";

export const separatorRecipe = tv({
  base: [
    "shrink-0",
    "bg-input",
    "data-[orientation=horizontal]:h-px data-[orientation=horizontal]:w-full",
    "data-[orientation=vertical]:w-px data-[orientation=vertical]:not-[[class^='h-']]:not-[[class*='_h-']]:self-stretch",
  ],
});

export type SeparatorVariantProps = VariantProps<typeof separatorRecipe>;
export type SeparatorRecipe = ReturnType<typeof separatorRecipe>;
export type SeparatorRecipeSlot = keyof SeparatorRecipe;
